// Standard questions, ccdvp. Original items written against the published exam guide. Built from content/en by tools/build-en.js.
window.QUESTIONS = window.QUESTIONS || {};
window.QUESTIONS.ccdvp = [
// ---- Domain 1: Advanced agent architecture and orchestration (17%) ----
{ id:'ccdvp-1-01', d:1, o:0, q:"A research agent has a supervisor that dispatches research to five workers in parallel. When one worker fails partway, the whole result comes back empty. Which fix is most sound as a production design?",
  c:["Each worker returns its result and failure in structured form; synthesize from what succeeded and state what is missing", "If any one fails, start every worker again from the beginning, and begin synthesis only once all results are in", "Drop the parallelism and give everything to one worker in sequence, making failures easier to isolate and retry", "Absorb worker failures by raising the supervisor's retry count to five, leaving the shape of the result unchanged"],
  a:[0], e:"Assume partial failure: synthesize from what succeeded and state the gap. Redoing everything or going serial throws throughput away." },
{ id:'ccdvp-1-02', d:1, o:0, q:"When delegating to subagents, choose the two designs that put the boundary of context isolation in the right place.",
  c:["Pass a subagent only the facts and constraints its task needs, not the parent's conversation history as it is", "Return a subagent's result as a summary with references to the grounds, not the raw tool output, to the parent", "Share the same context as it is between the parent and its subagents, so that their understanding never diverges", "Insert a subagent's output into the final answer with no verification by the parent, to cut round-trip latency"],
  a:[0,1], e:"Isolation means passing only the input needed and returning only compressed output. Sharing everything defeats isolation, and unverified insertion propagates failure." },
{ id:'ccdvp-1-03', d:1, o:0, q:"Human-in-the-loop is being added to an agent that processes refunds. Which placement is sound in production?",
  c:["Hold for approval only refunds above a threshold in amount or count; execute those within it and log them for audit", "Stop every refund until a person approves it, with the agent doing no more than preparing the draft of the refund", "Place no approval gate; people review everything in a daily batch after execution and reverse whatever was wrong", "Have the agent itself judge that it should ask for approval when the amount is high, leaving human checks to that"],
  a:[0], e:"Tier by risk. Approving everything halts operation, after-the-fact review does not suit irreversible acts, and model judgment alone does not stop things deterministically." },
{ id:'ccdvp-1-04', d:1, o:1, q:"A data migration agent that takes several hours starts over from the beginning whenever the process restarts partway. What should go in first for durable execution?",
  c:["Persist progress and intermediate results per step, with checkpoints that let it resume from there after a restart", "Raise the priority of the process so that restarts do not happen, and allocate it more memory and a longer timeout", "Fold the whole task into one long API call, so that no intermediate state has to be held on the process side", "Notify the person in charge at every restart, who checks how far it got and writes the instructions to continue"],
  a:[0], e:"Durability for a long-running agent is checkpoints and resumption. Hardening the environment or human intervention is not a root fix." },
{ id:'ccdvp-1-05', d:1, o:1, q:"In a design that saves the state of a long-running agent, which measure lets it resume even when the model version changes?",
  c:["Save the facts of the task, the completed steps and the next step as explicit data, independent of the shape of the history", "Serialize the conversation history as it is, and on resuming hand all of it to the new version to carry on from there", "When the version changes, discard the saved state unread and start again from the beginning, to keep things consistent", "Resume on the same version only, and get by operationally by finishing every task before the old version is retired"],
  a:[0], e:"State held as explicit data does not depend on the version or on the shape of the history. History saved as is is fragile against behavioral differences between versions." },
{ id:'ccdvp-1-06', d:1, o:2, q:"Invoice processing built as an agent has run in production for six months. Traces show 95% of cases going through the same four steps in the same order. Cost is twice the target. Which decision is sound?",
  c:["Move the mainstream four steps to a fixed workflow, and handle only the remaining 5% with the agentic design", "Keep the agentic design but switch to a smaller model, leaving the order of the steps to the model as before", "Cap the number of steps at four, force termination beyond that, and send those to people to hold cost down", "Keep operating as things are, and wait for a revision of model prices to bring cost within the target"],
  a:[0], e:"When production data shows the steps are fixed, a workflow gains predictability and cost. Shrinking the model alone leaves the uncertainty of order." },
{ id:'ccdvp-1-07', d:1, o:2, q:"Several teams each write their own agent loop, and the way failures are investigated differs by team. Choose the two things to put first as standards the teams adopt.",
  c:["Converge on a common harness (the Agent SDK, for example), aligning how tool calls, hooks and traces are emitted", "Share reusable patterns (approval gates, retries, the shape of results) as a library that every team can draw on", "Respect each team's implementation as it is, and standardize only the incident runbook and the on-call rota", "Unify all the teams on the most capable model, letting its ability absorb the differences in harness and loop"],
  a:[0,1], e:"Standardizing the harness and the patterns creates operational consistency. A runbook alone or a model alone leaves the implementation differences in place." },
{ id:'ccdvp-1-08', d:1, o:3, q:"A coding agent nears the context limit in long sessions and quality falls. Cost is rising too. Which measure should be tried first?",
  c:["Drop old tool output with context editing, and keep the key points by summarizing with compaction", "Force the session to end when the context fills up, and have the user start again from the beginning", "Write all tool output to files, returning only the file names to the model and not letting it read them", "Switch to a model with a larger context window, and carry on with the same conversation as it is"],
  a:[0], e:"Context editing and compaction first. Forced termination wrecks the experience, file names alone leave nothing to work with, and a larger window only postpones the problem." },
{ id:'ccdvp-1-09', d:1, o:3, q:"Part of the system instructions has to change in the middle of a conversation. Which way of changing them does not break the prompt cache?",
  c:["Place the added instruction after the cache boundary (on the side of recent messages), leaving the start as it is", "Rewrite the system prompt at the start, and carry on by rebuilding the cache on the next call that is made", "Mix the new instruction into the description text of a tool definition, and send the tool definitions updated", "Switch the model over to a different version, and carry on after building a fresh cache with the new instruction"],
  a:[0], e:"The cache matches on the prefix. Add changes after the boundary. Changing the start or the tool definitions invalidates the cache." },
{ id:'ccdvp-1-10', d:1, o:3, q:"An internal MCP server exposes 300 tools, and loading them all bloats the prompt. Which approach is sound?",
  c:["Use a mechanism that searches the tools and loads only the definitions needed (tool search, deferred loading)", "Shorten each of the 300 descriptions to a single line, and keep on loading all of them into context as before", "Merge the tools into one general execute tool, so that anything at all can be run through a string argument", "Put the less frequently used work out of scope to cut the tools down to 100, and keep on loading the rest"],
  a:[0], e:"A large tool catalog is kept outside the context and discovered when needed. A general execute tool goes against least privilege." },

// ---- Domain 2: Production integration, reliability and knowledge grounding (20%) ----
{ id:'ccdvp-2-01', d:2, o:0, q:"In production API calls, 429 (rate limit), 529 (overloaded), safety refusals and stops at max_tokens occur mixed together. Which retry design is correct?",
  c:["Retry 429 and 529 with exponential backoff, do not retry refusals, and handle a max_tokens stop by continuing generation or revisiting the limit", "Retry every error immediately the same number of times, and send whatever still fails after that on to the queue for people to deal with", "Fall back to another model or another region for everything, refusals included, and repeat until one of them finally returns an answer", "Treat a max_tokens stop and a 529 as errors and send the same request again, applying backoff to the 429 responses and to nothing else"],
  a:[0], e:"Handle each kind of error differently. Retrying a refusal or dodging to another model bypasses safety, and resending after a stop repeats the same result." },
{ id:'ccdvp-2-02', d:2, o:0, q:"A regional outage has left the API unresponsive. Choose the two sound resilience patterns.",
  c:["A circuit breaker stops calls once failures continue, and traffic switches to another region or another platform", "Graceful degradation is prepared: non-essential features (summaries, suggestions) are dropped and the core is returned", "Retry on every failure with no pause in between, and push all the queued requests through the instant it recovers", "Ignore feature differences at the fallback target, send the same request body as it is, and match only the result shape"],
  a:[0,1], e:"Breakers, fallback and degraded operation are the basics. Immediate retries make an outage worse, and platforms differ in features." },
{ id:'ccdvp-2-03', d:2, o:0, q:"A fallback to Bedrock was added, but in production only some requests fail. Which cause is most likely?",
  c:["Available features differ by platform (model versions, beta features, structured output), so requests do not pass through as they are", "Bedrock has no rate-limiting mechanism of its own, so the requests that flow in through the fallback are too many and it falls over", "Prompt caching is mandatory at the fallback target, so any request that carries no cache breakpoint gets rejected by the platform", "Clocks are out of step between the regions, so the signatures of some requests are judged to have expired and they are rejected"],
  a:[0], e:"Gaps in feature parity are the classic pitfall of a fallback. Adapt the request to the platform." },
{ id:'ccdvp-2-04', d:2, o:1, q:"A nightly batch classifies one million documents. It hit the same API under the same rate limit as the daytime real-time processing, and the daytime processing slowed down. Which design is sound?",
  c:["Move the nightly work to the Message Batches API, so that it does not consume the real-time side's rate limit", "Raise the retry count for the nightly work so that everything gets through in the end, and leave daytime as it is", "Stop real-time processing at night to put the batch first, handling requests that arrive overnight the next morning", "Put both kinds of traffic into a single queue served first come first served, absorbing priority in queue length"],
  a:[0], e:"Separate batch work from the real-time rate limit. The Batches API also halves the cost, and the two no longer compete." },
{ id:'ccdvp-2-05', d:2, o:1, q:"In a multi-tenant SaaS, heavy use by one company slowed responses for the others. Which is sound as quota and isolation?",
  c:["Separate usage caps and queues per tenant, and apply backpressure only to the tenant that goes over its cap", "Apply to raise the overall rate limit, and clear the congestion with more headroom and no tenant isolation", "Have operations staff watch the heavy tenants by hand, and contact them to hold back once it is noticed", "Slow the requests of every tenant by the same proportion, so that all of the tenants wait equally and fairly"],
  a:[0], e:"Per-tenant caps and isolation are the production basics. A bigger overall allowance does not change a structure where one company eats it all." },
{ id:'ccdvp-2-06', d:2, o:1, q:"Under high load, which combination of metrics tells you whether the constraint is the rate limit, token throughput or batch economics?",
  c:["The 429 rate and remaining-limit headers, input and output tokens per minute, and batch completion time and unit price", "CPU utilization on the app servers, remaining disk space, and network bandwidth use with its trend over that period", "The number of concurrent users, the number of logins and of screen transitions, and the spread of access at peak", "The model's accuracy, its hallucination rate and its refusal rate, and how each changes in the hours of heavy load"],
  a:[0], e:"The kind of constraint is told apart by rate-limit signals, token volume and batch economics. Infrastructure or quality metrics do not show it." },
{ id:'ccdvp-2-07', d:2, o:2, q:"The schema of a tool on a remote MCP server was changed, and production agents failed all at once. Choose the two change-management measures that prevent a repeat.",
  c:["Version the tools and schemas, keep the old version for a set period, and migrate in stages", "Point part of the traffic at the new version, watch, then widen it, rolling back on trouble", "Apply schema changes all at once late at night, and check behavior before work starts next day", "Stop validating arguments on the agent side, so that a schema of any shape at all is accepted"],
  a:[0,1], e:"Versioning and a staged rollout (with rollback). A late-night big bang or dropping validation is not change management." },
{ id:'ccdvp-2-08', d:2, o:2, q:"What should be done in production before migrating to a new model version?",
  c:["Run the new version on a regression evaluation set, measure differences in format, length, refusals and tool calls, and switch in stages", "A new version is assumed to be better than the old one, so switch all of the traffic over together on the day of the announcement", "Move to the new version with the prompts unchanged, and go back to the old version once a certain number of user complaints come in", "Stop use of the old version right after the new one is announced to force the migration, fixing the problems one by one afterwards"],
  a:[0], e:"Breaking changes in behavior are found by evaluation. Switch in stages, with rollback possible." },
{ id:'ccdvp-2-09', d:2, o:2, q:"A remote MCP server is going into production. Which authentication design is sound?",
  c:["Authorize each client with OAuth or similar, and grant tool permissions narrowed by scope", "Hand one fixed shared token to all clients, and guard access by IP restriction alone", "Publish with no authentication, and write “internal use only” in the tool descriptions", "Give the MCP server one admin credential, which it uses on behalf of every user"],
  a:[0], e:"Per-client authorization and scopes. Shared tokens and concentrated admin credentials breed leaks and privilege escalation." },
{ id:'ccdvp-2-10', d:2, o:3, q:"An app answers from 20,000 pages of internal regulations. For 30% of questions it “quotes an unrelated clause and answers with full confidence.” Which is the right order for diagnosing a retrieval-quality failure stage by stage?",
  c:["Look at each stage's output in order: ingestion and chunking → retrieval (recall) → reranking (precision) → generation (use of the grounds)", "Change to a higher model first and look for improvement; if nothing changes, swap the embedding model, and look at search parameters last", "Write “do not quote unrelated clauses” in the prompt, and if that does not work, make the chunks larger and reindex the full text", "Have people grade the final answers only to get a pass rate, and keep changing the wording of the prompt until it goes above 90%"],
  a:[0], e:"Diagnose a retrieval pipeline stage by stage. Looking at the final answer alone does not tell you which stage broke." },
{ id:'ccdvp-2-11', d:2, o:3, q:"Which is the right way to choose between agentic search (looking things up with tools each time) and a prebuilt RAG?",
  c:["With a large corpus and varied questions, make RAG the base; use agentic search for exploratory research whose steps change", "Agentic search is always more accurate than RAG, so replace all of it and skip the effort of building and updating an index", "RAG adds a large delay through retrieval round trips, so agentic search always suits the real-time uses better than RAG does", "Both find the same documents in the end, so choose whichever is simpler to build and operate and ignore the difference"],
  a:[0], e:"Choose by the trade-offs. RAG is predictable and fast; agentic search is flexible but costs more and takes longer." },
{ id:'ccdvp-2-12', d:2, o:3, q:"In a production app grounded in knowledge, choose the two grounding techniques that should be put in.",
  c:["Attach sources (document ID and passage) to answers, and answer “not found” when there are no grounds", "Emit confidence signals (match with grounds, agreement across documents), and send low ones to a person", "When the search comes back empty, fill in from the model's general knowledge so the answer flows on naturally", "Leave sources out because they make answers longer, keeping the grounds in internal logs and off the screen"],
  a:[0,1], e:"Sources, stated uncertainty and confidence are the pillars of grounding. Filling in from general knowledge mixes in ungrounded answers." },
{ id:'ccdvp-2-13', d:2, o:3, q:"In a RAG with vector search only, recall is low for questions containing product codes and proper nouns. Which improvement is sound?",
  c:["Make it hybrid search by combining keyword search (BM25, for example), and narrow the top results by reranking", "Double the size of the chunks, so that one chunk holds the product code together with the description around it", "Swap the embedding model for one with more dimensions and reindex, so that proper-noun vectors come out closer", "Show a note on screen guiding users to ask again with a description of the product and no product code in it"],
  a:[0], e:"Keyword search is strong on proper nouns and symbols. Hybrid plus reranking is the standard move." },

// ---- Domain 3: Observability and production monitoring (12%) ----
{ id:'ccdvp-3-01', d:3, o:0, q:"You want to investigate a failure in a production agent, but the logs hold only the “final answer.” What should be added first as instrumentation?",
  c:["Tie each turn and tool call into one trace, and record inputs and outputs, duration and token counts as spans", "Record and store the users' screen operations, and replay the period in question when a failure is reported", "Store every prompt sent to the model and every response in plain text forever, and search the full text later", "Keep a stack trace and the input only when an error occurs, recording nothing for responses that came back fine"],
  a:[0], e:"Distributed tracing lets you follow every step of one request. Keeping plain text forever goes against privacy, and errors alone cannot trace a quality failure." },
{ id:'ccdvp-3-02', d:3, o:0, q:"In a system for a customer with a zero data retention (ZDR) agreement, what should be done about records for debugging? Which is sound?",
  c:["Record no bodies, and make things traceable through metadata (token counts, latency, tool names, error types, hashes)", "ZDR is a promise about retention on the model provider's side, so your own logs may store all of the bodies as they are", "Record the bodies because debugging needs them, in a store with restricted access rights where every viewing is logged", "Keep no records of any kind, with a policy of reproducing the same input to investigate after a failure is reported"],
  a:[0], e:"Under privacy constraints, drop the bodies and keep observability through metadata. Honor the contract and your own policy together." },
{ id:'ccdvp-3-03', d:3, o:0, q:"Choose the two values that should be measured to diagnose cache performance.",
  c:["The values of cache_read_input_tokens and cache_creation_input_tokens in the usage of each response", "The trend of the cache hit rate, and a breakdown of prompt-prefix differences for requests that missed", "The average number of output tokens, and the number of sentences and paragraphs in each response over time", "How long users stay, the average number of questions per session, and the interval before they come back"],
  a:[0,1], e:"Look at the cache fields in usage, the hit rate, and the cause of misses (prefix differences). Output length and dwell time have nothing to do with the cache." },
{ id:'ccdvp-3-04', d:3, o:1, q:"Choose the two that are sound as SLIs for a support-response service that uses an LLM.",
  c:["Metrics of task quality, such as first-contact resolution or grounded answers", "Time to first token, and the p95 of the total response time for a request", "The parameter count of the model in use, and the size of its context window", "The development team's deployments per week, and its number of pull requests"],
  a:[0,1], e:"An SLI is the quality and speed the user feels. Model size and deployment counts are not SLIs." },
{ id:'ccdvp-3-05', d:3, o:1, q:"From the week after a model version update, answers grew longer and structured-output failures rose. Which monitoring design catches this early?",
  c:["Set quality metrics such as output length, format-validation failure rate and refusal rate, and alert on drift from the pre-update baseline", "Monitor the rate of HTTP 5xx errors and the rate of API timeouts, and raise an alert when either one of the two goes above its threshold", "Run a user survey once every week, and open a ticket for an investigation when satisfaction comes in lower than it was the week before", "Monitor total token usage and the billed amount daily, and raise an alert when either rises by 20% or more against the day before"],
  a:[0], e:"Drift after a version update is detected as a departure from the baseline of quality metrics. It does not show in HTTP errors." },
{ id:'ccdvp-3-06', d:3, o:1, q:"Which design for cost alerts is sound?",
  c:["Aggregate token consumption per tenant and feature, and alert on burn rate against budget and on abnormal spikes", "Check the bill at month end, revise next month's budget, and if over, ask for a review of heavily used features", "Monitor request counts only and alert on a threshold, checking token counts only when reading the billing detail", "Send no alerts; operations staff check the dashboard every morning and share what they notice in the team chat"],
  a:[0], e:"Hold token and cost telemetry at each granularity, and alert on rate and anomaly. Month end or human eyes are too late." },
{ id:'ccdvp-3-07', d:3, o:2, q:"An agent produces 2 million traces a day, and there are reports of “an odd answer now and then.” Reading individual traces does not find it. Which way forward is sound?",
  c:["Cut cohorts by signs of failure (retries, long loops, low confidence, negative reactions), aggregate by attribute, and look for skew", "Line all the traces up in time order and read them in turn, marking the ones that look abnormal, and go on until a pattern shows", "Pull out 10 at random and read them closely, and if no problem is found in them, conclude that the reports were simply mistaken", "Read every conversation of the users who reported it and nothing else, and treat it as a problem with how those users use it"],
  a:[0], e:"Large-scale traces call for aggregation and failure-cohort analysis. Reading one by one or a small random sample does not show systematic problems." },
{ id:'ccdvp-3-08', d:3, o:2, q:"With high-volume production traces, storing every body raises cost and retention problems. Which sampling design is sound?",
  c:["Sample the normal path at a fixed rate, and keep every trace with an anomaly such as an error, retry or latency overrun", "Store every one of the traces in full, with the retention period set to one day and automatic deletion the next day", "Sample at a flat 1%, keeping normal and abnormal traces at the same rate, and do all of the analysis on that 1%", "Do no sampling; delete all of the bodies, and keep only the ID and the timestamp of the trace for every single one"],
  a:[0], e:"Priority sampling that keeps the tail (the anomalies) thick. Flat sampling drops rare failures." },

// ---- Domain 4: Advanced debugging and incident response (10%) ----
{ id:'ccdvp-4-01', d:4, o:0, q:"In a multi-turn agent, answers that forget the original requirements increase from turn 10 onward. What should be looked at first to isolate the cause?",
  c:["In the trace, look at how the context was made up at turn 10, and check whether compaction or pruning dropped the requirements", "Switch the model to another version and replay the same conversation from the start, judging by whether the symptom shows again", "Have users rewrite the requirements on every turn, watch for a week or so to see if the symptom goes, and then consider the cause", "Check tool response times and timeout settings, to see whether a slow tool is causing a break in the middle of the conversation"],
  a:[0], e:"First establish as fact what was left in the context. Swapping the model or an operational workaround does not identify the cause." },
{ id:'ccdvp-4-02', d:4, o:0, q:"An agent answers “I can't help with that” only to one particular customer's requests. In investigating the cause, what is easily overlooked but must always be checked?",
  c:["Whether a model refusal is occurring as a failure (content in tool results or retrieved documents inviting a refusal)", "Whether that customer's network environment or type of browser has particular restrictions or a proxy configured", "Whether that customer's user settings differ from others in language or region, so that the screen appears broken", "Whether database disk usage or the number of connections is high only at the times of that customer's requests"],
  a:[0], e:"A refusal is a class of failure too. External content that entered the context can be the cause of a refusal." },
{ id:'ccdvp-4-03', d:4, o:0, q:"An agent non-deterministically gives the wrong amount of money 5% of the time. Which procedure is sound for isolating whether the cause is the model output, the harness, a tool or the data?",
  c:["In the failed traces, compare stage by stage the value the tool returned, the value the harness passed, the value the model read, and the source data", "Set temperature to 0 and run the same input 100 times, and if it no longer reproduces, call it solved as having been caused by model variation", "Put in a mechanism that collects the model output 100 times and takes a majority vote, pushing the errors down to a rate where they do not surface", "Add wording at the end of each answer that prompts the user to check the amount again, and have them report it when they find it is wrong"],
  a:[0], e:"Comparing values stage by stage identifies the source. Temperature or majority voting are fixes that hide the symptom." },
{ id:'ccdvp-4-04', d:4, o:0, q:"A RAG app gave “an answer different from what the document says.” Isolation showed retrieval was returning the right documents. What should be suspected next?",
  c:["Whether use of the grounds broke down at generation (general knowledge put ahead of retrieved text, or documents mixed up)", "Whether the embedding model lacks accuracy and, unable to tell similar documents apart, returns another with a close meaning", "Whether the chunks are too small, so that context before and after is cut and text is retrieved with its meaning changed", "Whether the index is updated too rarely, so that old versions of the documents are still left among the search results"],
  a:[0], e:"If retrieval is right, the failure is on the grounding (generation) side. Retrieval-side factors are ruled out as the cause." },
{ id:'ccdvp-4-05', d:4, o:1, q:"Two hours after a new prompt went to production, broken answer formats surged. What should be done first as incident response?",
  c:["Roll back to the previous prompt version to stop the damage, then investigate the cause and put a fixed version through evaluation", "Leave production as it is until the cause is fully identified and a fix confirmed, putting a grasp of the blast radius first", "Announce to users that formats are breaking, and guide them to read the answers ignoring the format until it has been fixed", "Edit the new prompt directly in production with immediate effect, adjusting at short intervals until the breakage settles"],
  a:[0], e:"Mitigation (rollback) comes first, root-cause analysis after. Piling fixes onto production invites a secondary failure." },
{ id:'ccdvp-4-06', d:4, o:1, q:"After an incident has settled, choose the two things that should be done as the “learning loop.”",
  c:["Add the inputs that reproduce the failure to the regression set, so that the same change does not pass again", "Look at why detection came late, and widen the monitoring metrics and the range that the alerts cover", "Identify who made the change to make responsibility clear, and end prevention with a caution to that person", "Decide to respond by hand with the same steps if the same failure occurs, and write that up in the runbook"],
  a:[0,1], e:"Turn an incident into regression evaluation and wider monitoring. Pursuing individual blame or fixing a manual response in place is not learning." },
{ id:'ccdvp-4-07', d:4, o:1, q:"A quality regression is under way, but it is unclear whether the cause is an update on the model provider's side or a change of your own. Which way of triaging is sound?",
  c:["Line up your own recent changes (prompts, tools, data, settings) in time order, and revert first those that overlap the start of the regression", "Judge it to be a failure on the model provider's side and wait for recovery, watching the status page for updates while notifying your users", "Revert every change made in the last week to its previous state at the same time, and once the regression settles, put them back one at a time", "Watch and wait until the reports from users reach a certain number, and begin the response once the size of the impact has become clear"],
  a:[0], e:"Matching the change history against the time comes first. A flat assertion or reverting everything at once loses sight of the cause." },

// ---- Domain 5: Evaluation engineering and quality assurance (12%) ----
{ id:'ccdvp-5-01', d:5, o:0, q:"Quality in production wobbles every time a prompt changes. Which setup is sound as an evaluation gate in CI/CD?",
  c:["Run golden-set accuracy, format validation and safety checks automatically, and stop the deployment when below the bar", "Watch production traffic for a day after deploying, and go back to the previous version if complaints or bad reactions rise", "A developer tries about five questions by hand at each change, and deploys to production if nothing looks wrong", "Evaluate once a quarter in one go, and ship the changes in between to production on developer review alone"],
  a:[0], e:"An automated evaluation gate before release is the release criterion. After-the-fact observation or a few manual tries is not a gate." },
{ id:'ccdvp-5-02', d:5, o:0, q:"On a golden set used for a year, every change now scores 99%. Problems keep appearing in production. What is happening?",
  c:["The evaluation set has saturated and no longer tracks production. Add production failures to update difficulty and coverage", "The model has become smart enough that the evaluation set has done its job. Stop evaluating and just monitor production", "The golden set is right, so production problems lie in how users use it. Hand out a guide to using the product", "Raise the passing bar from 99% to 100%, so that a change that fails even one question does not go to production"],
  a:[0], e:"Saturation, contamination and thin coverage are problems of the suite's validity. Keep updating it with production failures." },
{ id:'ccdvp-5-03', d:5, o:0, q:"In evaluating a RAG app, choose the two metrics to measure besides the correctness of the answer.",
  c:["Retrieval precision and recall (whether the right documents ranked high)", "Grounding (whether the answer is supported by the retrieved documents)", "The character count of the prompt, and input tokens for a single call", "The size of the index, and the number of dimensions of the vectors"],
  a:[0,1], e:"Measure retrieval quality and grounding separately. Character counts and sizes are not quality metrics." },
{ id:'ccdvp-5-04', d:5, o:1, q:"LLM-as-judge scores do not agree with human review. A look showed that longer answers were scoring higher. Which fix is sound?",
  c:["State in the rubric that length is not scored, and verify with same-content answers of varied length that the verbosity bias is gone", "Change the model used as the judge to a higher version, and return it to operation without confirming that agreement with people rose", "Human review takes time, so stop it, and use the judge's scores alone as the truth for the decisions that are made about quality", "Write in the prompt that every answer must be limited to 200 characters or fewer, so that no difference in length arises at all"],
  a:[0], e:"Identify the bias and fix it with the rubric and verification. Swapping the model alone verifies nothing." },
{ id:'ccdvp-5-05', d:5, o:1, q:"With a judge that compares two answers, A tends to win when A is shown first. Which is the right remedy?",
  c:["Score twice with the order swapped, and adopt the result only when the two agree (canceling position bias)", "Always place the one expected to be good first, absorbing the effect of order by raising the scoring threshold", "Drop comparison for absolute scoring one at a time; position has no effect by structure, so skip verification", "Raise the evaluation sample size tenfold, on the view that with large numbers the effect of position averages out"],
  a:[0], e:"Position bias is canceled by swapping the order. A larger sample does not remove a systematic skew." },
{ id:'ccdvp-5-06', d:5, o:1, q:"After the version of the judge model was raised, the average score of the same set of answers fell by 0.6. What should be done?",
  c:["Recalibrate the old and new judges on a human-labeled set, and reset the thresholds before using the new one", "Judge that the score fell because production quality fell, and start improving the prompt that generates answers", "Adopt a policy of never raising the judge version, and keep using current scoring until the old one is retired", "Correct by adding the 0.6 difference in averages to every score of the new judge, and keep the thresholds as is"],
  a:[0], e:"This is judge drift. Recalibrate against human labels. Adding the difference ignores the change in the distribution." },
{ id:'ccdvp-5-07', d:5, o:2, q:"Offline evaluation passed, but production quality is a concern. Choose the two sound ways of measuring quality online.",
  c:["Sample part of production traffic and score it afterwards (by people or a judge), looking at the gap from offline", "Split old and new setups by A/B, and compare on metrics fit for the task (accuracy for extraction, acceptance for generation)", "Count only the number of likes that users press, and judge that quality is being held if the count is up on the week before", "Treat production measurement as unneeded when offline evaluation passes, investigating only when users report a failure"],
  a:[0,1], e:"Live sampling and A/B are how production quality is measured. Likes alone are skewed." },
{ id:'ccdvp-5-08', d:5, o:2, q:"Which is sound as a production quality metric for agentic tasks (reaching a goal through several tool calls)?",
  c:["Task completion rate, with steps to completion, tool failure rate and human intervention rate", "Output tokens per response, and the average number of sentences that a response contains", "Grammatical correctness of responses, and the share whose register follows the style guide", "The model's temperature setting, and the size of the token budget allocated to thinking"],
  a:[0], e:"Choose metrics that fit the kind of task. For agentic work: completion, efficiency and intervention rate." },

// ---- Domain 6: Cost and latency optimization at scale (8%) ----
{ id:'ccdvp-6-01', d:6, o:0, q:"Monthly cost is surging. Usage data shows 80% of input tokens were the same system prompt and tool definitions. Which measure should be taken first?",
  c:["Place a cache breakpoint on the stable prefix (system prompt and tool definitions), and monitor the cache read rate", "Switch every request to a small model to lower the unit price, winning quality back by prompt work and few-shot", "Cut the system prompt and the tool definitions to half their length, and watch in production how behavior changes", "Put a cap on the number of requests per user per day, and have the users who exceed it wait until the next day"],
  a:[0], e:"The dominant cost driver is repeated input. Handle it with caching, and confirm the effect in the usage data." },
{ id:'ccdvp-6-02', d:6, o:0, q:"70% of inquiries are simple classification and 30% are complex judgment. Which design lowers cost soundly?",
  c:["A cascade (routing): a small model handles everything first, and only low-confidence cases go up to a higher model", "Handle everything with the higher model to keep quality even, and absorb the cost by making the prompts shorter", "Handle everything with the small model to minimize cost, treating lower quality on the complex 30% as acceptable", "Have users declare how hard their inquiry is, and build a screen that lets them choose the model by that declaration"],
  a:[0], e:"Model routing and cascades are the standard for cost optimization at scale. Add cheap paths while holding the floor on quality." },
{ id:'ccdvp-6-03', d:6, o:0, q:"Which mechanism is sound for keeping to a budget per tenant?",
  c:["Meter token consumption per tenant, warn at a threshold, and at the cap switch to degraded mode (a small model) or stop", "Total up consumption per tenant at month end and bill the overage, proposing a plan review at next month's renewal", "Set one cap shared by all tenants to hold total consumption down, leaving the split between tenants to first come", "Keep no budget in the system; sales agrees a cap with each customer verbally, and phones when it looks like going over"],
  a:[0], e:"Run the loop of metering → warning → enforcement by machine. Billing afterwards or a shared cap is not a per-tenant budget." },
{ id:'ccdvp-6-04', d:6, o:1, q:"A chat is said to be “slow.” Measurement shows 0.8 seconds to the first token and 12 seconds in total. Which measure works best?",
  c:["Display incrementally with streaming, bringing the perceived wait close to the time to first token", "Lower the temperature to reduce variation in output, so generation converges sooner and total time falls", "Add prompt caching to speed up input processing, cutting the total time down a long way from 12 seconds", "Raise max_tokens so it does not stop partway, improving the feel because no regeneration takes place"],
  a:[0], e:"When TTFT is short and the total is long, improve the perceived speed with streaming. Caching works on the input-processing (TTFT) side." },
{ id:'ccdvp-6-05', d:6, o:1, q:"An agent calls four independent tools one after another in a single turn, taking 8 seconds in all. Which design lowers latency?",
  c:["Execute the independent tool calls in parallel, and hand the results together to the next turn", "Merge the four tools into one large tool, so that the model gets everything in a single call", "Drop the tool calls and have the model guess from its knowledge, using tools only when in doubt", "Cache each tool's results forever, and skip the call from the second time for the same arguments"],
  a:[0], e:"Parallelizing independent calls is the basic move. Replacing them with guesses wrecks accuracy." },
{ id:'ccdvp-6-06', d:6, o:1, q:"The system runs at high reasoning effort, but latency is the bottleneck on a simple extraction task. Which adjustment is sound?",
  c:["Lower the effort level to match the difficulty of the task, and confirm by evaluation that quality does not fall", "Keep effort at maximum always to protect quality, absorbing the delay with longer timeouts and a note to users", "Double the timeout to reduce failures, raising the completion rate while leaving the latency itself unchanged", "Cache the extraction results so the same input is not recomputed (the input documents differ every time)"],
  a:[0], e:"Tune effort to the task, and back it with evaluation. If the input differs every time, a cache does nothing." },

// ---- Domain 7: Runtime guardrails and production security (11%) ----
{ id:'ccdvp-7-01', d:7, o:0, q:"You want a production coding agent to be unable to run `rm -rf` or `DROP TABLE`. Which technique stops it deterministically?",
  c:["Inspect for dangerous command patterns in a hook before tool execution (PreToolUse), and block execution on a match", "Write “do not run destructive commands” in bold in the system prompt, with examples added, for the model to obey", "Put a step in the prompt that has the model ask itself “is this dangerous?” before running, and stop if it judges so", "Check the command logs daily after execution, and if there are dangerous commands, contact the owner to recover"],
  a:[0], e:"Prevent irreversible actions with deterministic enforcement such as hooks. Prompts and self-questioning are probabilistic, and after the fact is too late." },
{ id:'ccdvp-7-02', d:7, o:0, q:"An input filter has many false positives, and complaints are coming in because legitimate inquiries are rejected. Which adjustment is sound?",
  c:["Collect and classify the rejected cases, and revise thresholds and rules while measuring the balance of false positives and negatives", "Remove the filter and let everything through, finding the problem inputs afterwards in the logs and dealing with them individually", "Make the filter stricter still to lean to the safe side, and show wording that prompts the rejected users to enter their text again", "Apologize individually to the users who were rejected and handle them by hand, leaving the filter settings exactly as they are"],
  a:[0], e:"Tuning false positives and false negatives is part of operating a guardrail. Neither removing it nor tightening it across the board is a solution." },
{ id:'ccdvp-7-03', d:7, o:0, q:"You want to allow an agent web access and code execution. Which placement protects the production systems?",
  c:["Run it in a sandbox that cannot reach production credentials or networks, and allow only the egress that is needed", "Run the agent directly on the production servers, keeping a log of every command and protecting by monitoring", "Forbid web access and allow only code execution in production, with people handing over any data to be fetched", "Give the agent's execution user admin rights, removing failures from missing permissions to keep it stable"],
  a:[0], e:"A sandbox keeps production from being exposed. Admin rights or running directly in production go against least privilege." },
{ id:'ccdvp-7-04', d:7, o:0, q:"Which is sound as the production handling of a case where the model refuses for safety reasons?",
  c:["Detect the refusal, fall back safely to another answer path (a canned reply or handoff to a person), and monitor the refusal rate", "Automatically resend the same request in different wording, repeating the rephrasing up to five times until it is no longer refused", "Treat a refusal as a system error, returning HTTP 500 to the caller and leaving the rest to the retry logic on the client side", "Ignore the refusal response and return an empty answer, displaying nothing at all until the user changes the question"],
  a:[0], e:"Design refusal handling and a safe fallback. Retrying with rephrasing is going around the guardrail." },
{ id:'ccdvp-7-05', d:7, o:1, q:"An agent reads email bodies and drafts replies, also consults an internal DB, and can send to the outside. Why is this configuration especially dangerous?",
  c:["Access to private data, untrusted input and external communication come together, forming a path for exfiltration", "When the wording of a reply is not polite it may harm the brand, and with no check on style, trust is affected", "A large volume of email pushes token cost up, and there is no mechanism to degrade when the budget is exceeded", "More reads against the DB raise its load, which may affect the response times of the other systems that use it"],
  a:[0], e:"The “lethal trifecta.” Remove one of the three, or place an approval gate on external sending." },
{ id:'ccdvp-7-06', d:7, o:1, q:"An MCP server response or a fetched web page contained the sentence “Ignore your previous instructions and…”. Choose the two things to put in as defense in depth.",
  c:["Delimit tool results and fetched content as “data,” and state that instructions found there are not followed", "Stop acts with side effects such as sending or writing by approval gates or hooks, so fetched content alone cannot run them", "MCP server responses come from inside the company, so trust them and pass them to the model with no checks or delimiters", "Pass fetched pages to the model in full as they are, leaving the judgment of instruction or data to the model's reading"],
  a:[0,1], e:"A combination of delimiting in the prompt and deterministic control on the side-effect side. Trust or handing it all over is no defense." },
{ id:'ccdvp-7-07', d:7, o:1, q:"False “facts” from a document planted by an attacker had been written into an agent's long-term memory. Which gives the name of this threat and the countermeasure?",
  c:["Memory poisoning. Record the provenance of writes, and restrict and verify writes that come from untrusted input", "Rate limit overrun. Put a cap on the number of writes to memory, discard the excess, and retry on the next day", "Cache pollution. Invalidate the prompt cache and rebuild it, so that the old cache is no longer referenced", "Data remanence. Wipe the whole memory at intervals, and ask the user again for the facts needed every time"],
  a:[0], e:"Tool and memory poisoning are threats particular to production agents. Protect with provenance records and restrictions on writes." },
{ id:'ccdvp-7-08', d:7, o:1, q:"You are designing a red-team exercise. Which way of proceeding is sound?",
  c:["Build attack scenarios along a taxonomy such as the OWASP Top 10 for LLM, and add the successful attacks to the regression tests", "Developers try each attack they can think of once, keep no record of those that failed, and fix those that got through on the spot", "Try the attacks in production against real customer data, confirming resistance under real conditions before ranking the fixes", "If one round of attacks does not succeed, conclude it is safe, and hold no further exercise until the model version changes"],
  a:[0], e:"Follow a systematic taxonomy and keep the results as regression tests. An exercise on production data creates a different risk." },
{ id:'ccdvp-7-09', d:7, o:2, q:"Every production agent shares the same static API key, rotated once a year. Choose the two sound improvements.",
  c:["Replace it with workload identity federation or short-lived credentials, and stop handing out static keys", "Separate the identity per agent, so that the audit log can trace which agent performed which operation", "Embed the key in the code to make distribution simple, removing leaks from mishandled environment variables", "Go on sharing the key as before, and extend log retention to one year to make later investigation easier"],
  a:[0,1], e:"A shared static key causes leaks and untraceability. Move to separate identities and dynamic credentials." },
{ id:'ccdvp-7-10', d:7, o:2, q:"Which is sound as the “security-relevant agent actions” that should be kept in the audit log?",
  c:["Who (which agent, on whose behalf) ran which tool, with which arguments, when, and with what result", "The full text of the model's internal reasoning, with every option weighed and not chosen on each turn", "The user's operation history on screen, with dwell time, scroll position and the buttons pressed", "The diffs of changes to the agent's source code, with the full build log and tests of every deployment"],
  a:[0], e:"An audit log is the who, what, when and how of actions. Full reasoning text and screen operations are not the subject of an audit." },

// ---- Domain 8: Operating agent fleets for software delivery (10%) ----
{ id:'ccdvp-8-01', d:8, o:0, q:"You want eight coding agents to do a large refactor in parallel. Which design reduces conflicts?",
  c:["Split the tasks at module boundaries, have each agent work in an isolated worktree, and decide the merge order first", "Have the eight agents edit in the same working tree at once, with a person sorting the diffs and resolving conflicts last", "Have one agent do all of it in sequence, giving up on parallelism so that conflicts cannot occur in principle", "Assign at random by file and proceed at once, later taking the larger change for whichever files conflict"],
  a:[0], e:"Isolated worktrees, decomposition along boundaries, and a merge strategy decided in advance. Simultaneous edits in one tree become a mountain of conflicts." },
{ id:'ccdvp-8-02', d:8, o:0, q:"Fleet telemetry shows that “only one kind of task takes three times as long, and half of them fail.” Which is the most likely fleet-level failure mode?",
  c:["The context that kind needs (conventions, how to run the tests) is not being passed, so it repeats exploration and trial", "A failure on the model provider's side is occurring in those hours, and only that kind of task happens to coincide with it", "Network bandwidth is short, and the download of the dependency packages fetched by that kind of task is running slow", "The environment of the developer in charge of that kind has a problem, delaying agent startup until the time runs out"],
  a:[0], e:"Skewed failure in a fleet tends to come from gaps in the task definition or context. Look by kind from the telemetry." },
{ id:'ccdvp-8-03', d:8, o:1, q:"AI code review is being introduced. What should be done before giving it the power to block merges?",
  c:["Run it in shadow mode alongside human review first, measure agreement and false-positive rates, then make it a gate in stages", "Operate it as a merge gate from day one, and when developers voice their discontent, take the gate off at that point and adjust", "Abolish human review and use AI alone, removing the wait for review entirely and putting the speed of development first", "Make it a rule that every AI comment must be addressed, so that nothing can be merged until all of them have been dealt with"],
  a:[0], e:"The order is shadow mode → calibration → gating. A gate from day one stops development with false positives." },
{ id:'ccdvp-8-04', d:8, o:1, q:"The volume of generated code has exceeded review capacity. Choose the two sound designs for human oversight.",
  c:["Tier changes by risk (production impact, security, irreversibility), with people reviewing only high risk in depth", "Put tests, static analysis and AI review in front, with people looking only at what has passed that front stage", "Skip review and merge automatically, operating by finding problems through production monitoring and fixing later", "Pause code generation for a time, and put in no new tasks until the processing of reviews has caught up again"],
  a:[0,1], e:"Tier by risk, and save people's time with an automated front stage. Neither skipping nor stopping is a solution for production operation." },
{ id:'ccdvp-8-05', d:8, o:2, q:"An agent is being set up to do first response automatically when CI fails. Which design for unattended operation is sound?",
  c:["Automate up to investigating and drafting a fix, wait for human approval to land on main, and show progress by checkpoints and notices", "Give the agent push rights to main so fixes land automatically, with people checking the results together the following morning", "Page the owner at every failure, with the agent only sending the failure notice and doing no investigation or drafting of a fix", "When the agent could not handle it, record nothing and exit quietly, starting up again at the next failure that CI happens to hit"],
  a:[0], e:"Unattended operation means designing what is automated and how far, where it stops, and who is told. Exiting silently and full permissions are out." },
{ id:'ccdvp-8-06', d:8, o:2, q:"An agent creates dependency-update PRs on a nightly schedule. Which controls should be in place in production?",
  c:["Design checkpoints, notification of results and where to escalate when unsure, and merge PRs only after human review", "Merge update PRs automatically when tests pass, with a person checking next morning and reverting if there is a problem", "Have the agent create PRs with no notification, reviewed whenever a developer happens to notice them in the list", "Keep no record of failures and repeat the same job the next night, notifying only after three failures in a row"],
  a:[0], e:"The three-piece set for unattended runs is checkpoints, notification and escalation. Automatic merging does not match the irreversibility." },
{ id:'ccdvp-8-07', d:8, o:3, q:"The whole company is starting to use coding agents. What should be put in first as organization-wide configuration?",
  c:["Set floors for permission modes and allowed tools in managed settings, put MCP servers on an allowlist, and centralize telemetry", "Let each developer add MCP servers and Skills freely, putting convenience and speed of trial first and seeing how things go", "Tell everyone to run with `bypassPermissions` to remove the effort of confirming, maximizing speed to push the rollout forward", "Collect no telemetry, and start with a policy of interviewing the person concerned to find the cause when a problem occurs"],
  a:[0], e:"Decide centrally the floor that must be protected (permissions, allowlist, telemetry), and leave the rest to teams." },
{ id:'ccdvp-8-08', d:8, o:3, q:"You want to share a Skill and an MCP server that one team built with the whole company. Choose the two that are sound as governance.",
  c:["Before sharing, review against bars for quality (tests, accurate descriptions) and safety (permissions, egress, secrets)", "Make the version and the owner clear, so that on trouble it can be rolled back and someone can be contacted", "It is useful, so skip the review and distribute it company-wide; the team that built it fixes problems as they arise", "After sharing it is the building team's responsibility, and the teams using it need not check contents or permissions"],
  a:[0,1], e:"Sharing goes through a bar for quality and safety, and has an owner and a version. Distribution without review is a supply-chain risk." },
{ id:'ccdvp-8-09', d:8, o:3, q:"Some teams use coding agents through several clouds (the direct API, Bedrock, Vertex). Which mechanism keeps the configuration consistent?",
  c:["Centralize routing, authentication and logging in a gateway, which absorbs the differences between platforms", "Each team manages its own credentials and settings, absorbing platform differences in the team's own runbook", "Standardize on one platform and forbid the rest (with exceptions for teams whose contracts do not allow it)", "Keep telemetry in a separate place for each platform, with a person totaling it monthly to compare the gaps"],
  a:[0], e:"Centralizing in a gateway creates parity and observability in production." },
// ---- Added from study notes ----
{ id:'ccdvp-1-11', d:1, o:0, q:"A design is proposed that hands “reproduce the bug → investigate → fix” to three subagents in turn. Which assessment follows the criteria for delegation?",
  c:["A sequential pipeline that depends on the previous stage's findings does not suit subagents. The work along the way matters to the parent, so do it in the parent's thread", "It is ideal, since each stage can work in an independent context. Passing each subagent's summary to the next also keeps the parent's own context from being polluted", "Starting the three in parallel makes it faster. Reproduction, investigation and the fix are independent of one another, so they may all go forward at the same time", "Giving the subagents the persona of a “debugging expert” raises quality even when the stages run in sequence, so the proposed design may be adopted as it stands"],
  a:[0], e:"The criterion for delegating is whether the work along the way matters to the parent. Poor fits: sequential pipelines, a persona alone, running tests." },
{ id:'ccdvp-1-12', d:1, o:0, q:"A subagent keeps working beyond the scope of the request and overruns. Which is the design-level remedy?",
  c:["Define the output format in its system prompt. The format becomes the cue to finish and prevents overrun", "Remove all its tools and make it read-only. If it cannot write, overrunning does no harm to anything", "Add an instruction for the parent to check progress every turn, returning the judgment to the parent", "Lower the subagent's temperature. Once output is stable, actions beyond the scope decrease as well"],
  a:[0], e:"Four points of design: a specific description, a defined output format, a field for reporting failures, and the minimum tools needed." },
{ id:'ccdvp-1-13', d:1, o:0, q:"Which is the reason that leaving code review to a subagent is an advantage?",
  c:["A fresh context that does not know how the code came about looks harder. The parent is pulled by the history of writing it", "A subagent runs on a higher model than the parent does, so it can find more of the problems than the parent would", "The review result arrives as a summary, so the parent is spared from reading through the output of failed tests", "A subagent inherits the parent's Skills automatically, so there is no need to specify the policy for the review"],
  a:[0], e:"A subagent does not inherit the parent's Skills. Running tests is a poor fit, since the summary hides the failure output." },
{ id:'ccdvp-1-14', d:1, o:1, q:"Which point is stressed about the steps for starting a session in Claude Managed Agents?",
  c:["Open the event stream before sending the first message. Event history is kept on the server and can be fetched again after a disconnect", "Send the first message and then open the event stream. If it is opened first, the empty stream times out before anything arrives", "Do not use the event stream; wait for `session.status_idle` by polling it. A stream is too fragile when connections are dropped", "Create a new environment (sandbox) again for every single session that is started. An environment cannot be used a second time"],
  a:[0], e:"Four elements: agent, environment, session and events." },
{ id:'ccdvp-1-15', d:1, o:1, q:"A Managed Agents session went to `session.status_idle`. How do you tell whether it is finished or waiting for input?",
  c:["Look at `stop_reason.type`: `end_turn` means finished, and `requires_action` means waiting for input", "If the last event is text it is finished; if it is a tool call, treat it as waiting and decide from there", "Judge by elapsed time in the session: with no events for a set time, treat it as finished and close up", "`status_idle` always means finished. Waiting for input is signaled by an event with a different status"],
  a:[0], e:"Decide by the `stop_reason.type` of `session.status_idle`." },
{ id:'ccdvp-1-16', d:1, o:2, q:"A policy of “always pass the tests before opening a PR” was written into a Skill, but it is sometimes not followed. Which is the remedy?",
  c:["A Skill is advisory control. For a policy that must always hold, put a hook or a required PR check behind the Skill", "Rewrite the Skill in a strong imperative and put “absolutely” at the top. If the wording is strong it is obeyed", "Move the Skill into CLAUDE.md. CLAUDE.md is read every time, so it is followed more reliably than a Skill is", "Distribute the Skill through managed settings. A managed Skill is read with top priority, so it is obeyed"],
  a:[0], e:"A Skill is advisory; a hook is deterministic." },
{ id:'ccdvp-1-17', d:1, o:2, q:"You want a custom subagent to use the same Skill as the parent. Which account is correct?",
  c:["A subagent does not inherit Skills the parent invoked. Preload them in the `skills` field of the custom subagent", "A subagent shares the parent's context, so Skills the parent invoked can be used as is with nothing specified", "A Skill applies to the whole project, so within the same repository a subagent can use it with nothing done", "Skills cannot be given to a subagent. Copy the steps needed directly into the subagent's own system prompt"],
  a:[0], e:"Sharing Skills: the repository, plugins, or managed settings (top priority when names collide)." },
{ id:'ccdvp-1-18', d:1, o:3, q:"Which correctly lists the “four patterns of context management”?",
  c:["Fetching when needed (a design pattern), server-side compaction, prompt caching, and the memory tool (stored on the client side)", "Tuning temperature, limiting max_tokens, shortening the system prompt, and cutting tool definitions. Sending less is the basis", "Splitting the conversation, inserting summaries by hand, switching models, and moving to a model with a larger context window", "Streaming, batch, parallel tool calls, and programmatic tool calling. The amount is reduced by the shape of the processing"],
  a:[0], e:"The whole window is sent again every turn. Compaction is a summary, so detail can drop out." },
{ id:'ccdvp-2-14', d:2, o:0, q:"You want an agent to carry out production releases. Which form follows “autonomy graded by environment”?",
  c:["In production it prepares; the release owner approves, and a hook that checks for an approved change ticket enforces the gate. Rollback is rehearsed", "Run production with the same autonomy as development and roll back on failure. If rollback is fast, neither approval nor a hook is needed at all", "Do not run it in production at all. Stop at staging, with every production operation done by people by hand. The agent makes no proposals either", "Use a higher model in production only. With a smart model, approval and hooks are unneeded, as the model's ability lowers the failure rate enough"],
  a:[0], e:"Development is free, staging is in between, and production goes as far as preparation." },
{ id:'ccdvp-2-15', d:2, o:0, q:"In a production pipeline running with `--permission-mode dontAsk`, the release was left off the allowlist and the hook's allow decision was made the only way through. What happens when the hook fails to start?",
  c:["A call that needs confirmation is denied under `dontAsk`, so the release does not run. It fails to the safe side", "With no hook it runs without confirmation. `dontAsk` is the mode that skips every one of the confirmations", "The decision becomes ask, and it waits without limit for a person. The pipeline stops, but nothing is run", "Claude Code itself exits with an error. The pipeline as a whole is then treated as having failed its run"],
  a:[0], e:"If the hook does not run, the result is a denial." },
{ id:'ccdvp-2-16', d:2, o:1, q:"Which is recommended as the first step in building Claude Code into CI/CD?",
  c:["Start from a read-only stage (such as triaging a failed build), and keep writes inside the existing gates. The result arrives as a PR", "Start from auto-merge. Automate the stage with the largest effect first, and return to read-only if problems arise. Small starts show little", "Start from automating production deploys. It is the slowest stage so the effect is easy to see, and with rollback a failure can be undone", "Replace every stage at once. Putting it in partially blurs the line between people and AI, so nobody knows how far it has been entrusted"],
  a:[0], e:"Execution is inside a sandbox. Use short-lived, narrowly scoped tokens, and give it no production credentials." },
{ id:'ccdvp-2-17', d:2, o:2, q:"Deploy operations for staging and production are being exposed as MCP tools. Which setup lets permissions differ by environment?",
  c:["Make a separate MCP server per environment. Permission rules name the server and the tool, so the allowlist can tell environments apart", "Put a tool with an `env` argument on one server. The allowlist looks as far as argument values, so a rule can deny production alone", "One server will do if the tool name includes the environment. The allowlist decides by tool name only and does not look at the server", "Distinguish the environments in the system prompt. Write “do not touch production” and the tools can be shared under one allowlist"],
  a:[0], e:"Make release, status check and rollback into MCP tools." },
{ id:'ccdvp-2-18', d:2, o:3, q:"Which account of how the web search tool is handled is correct?",
  c:["It is a server tool, so it runs on Anthropic's side; no handler and no returning of tool_result are needed. Add one entry to tools", "It is a client tool, so you must call a search API yourself and return a tool_result. A handler and resend handling are needed", "It is provided as an MCP server, so register it in `.mcp.json` first. The definition arrives from MCP and is not written in tools", "Writing “search if needed” in the system prompt enables it automatically. Nothing is added to tools and no setting is needed"],
  a:[0], e:"`allowed_domains` can restrict where it searches (no protocol; subdomains are included)." },
{ id:'ccdvp-2-19', d:2, o:3, q:"In a long process that uses web search, `stop_reason` came back as `pause_turn`. Which handling is correct?",
  c:["Send the response's content back as an assistant message with the same tool settings, and it continues", "It is an error, so redo the same request from the start. Cutting the tool settings makes it less likely", "It is the signal of completion, so join the text blocks in content, return them to the user, and finish", "It is the signal that max_tokens was reached, so raise the limit and then send the same request again"],
  a:[0], e:"The answer can be split across several text blocks, so join them. Search results are in separate blocks." },
{ id:'ccdvp-3-09', d:3, o:0, q:"Compliance says, “We want to check what the agent answered a customer in a certain session last week.” Which answer follows the distinction between the records?",
  c:["The Compliance API. It is the only record that includes the conversation content; audit logs (metadata) and OpenTelemetry do not answer this", "The audit log. Who did what and when is kept there, so the content of the answer can be traced from it. Compliance API is just another name", "The OpenTelemetry export. Traces include the inputs and outputs of tool calls, so the body of the answer is there even on default settings", "None of them holds it. Conversation content cannot be had unless the app stored it separately; Anthropic's side keeps metadata alone"],
  a:[0], e:"When the question is “what was said,” the answer is the Compliance API." },
{ id:'ccdvp-3-10', d:3, o:0, q:"Which point needs care in a plan to enable records for audit?",
  c:["Enable records before use begins. The period before enabling cannot be filled in later. Route records nobody reads into an existing review process", "Enable records once a problem occurs. Enabling reaches back to cover the past as well, so turning it on early only adds to the cost of storage", "Keep retention short and extend it when needed. What was deleted under a short setting can be restored later, so the setting may change freely", "OpenTelemetry includes conversation content by default, so keep it disabled on personal-data grounds. Metadata holds no personal data at all"],
  a:[0], e:"Shortening retention deletes content that does not come back. OpenTelemetry in most setups does not include content by default." },
{ id:'ccdvp-3-11', d:3, o:1, q:"Which is the correct grading of monitoring by “control bands”?",
  c:["1σ is record only, 2σ is read-only diagnosis, and 3σ acts only by PR or a pre-approved runbook. Detection is done by a deterministic script", "Page a person at 1σ, roll back automatically at 2σ, and stop the service at 3σ. Detection is left to the model, for a call that weighs context", "Take the same response (rollback) at 1σ, 2σ and 3σ alike. Splitting into grades delays the response and ties judgment to individuals", "Set thresholds as fixed values and do not use σ. Past averages move and are no baseline, and fixed values are easier to explain to others"],
  a:[0], e:"Slow-moving change is picked up by run rules (the Western Electric rules)." },
{ id:'ccdvp-3-12', d:3, o:1, q:"A team asks, “Please raise our monthly spend cap.” Which stance is right?",
  c:["Make it a trigger to look into the cause, not an automatic approval. Default model and effort settings affect spend more than the cap does", "Raise the cap automatically to match actual use. Work stopping at the cap is the bigger loss, and looking into the cause can come afterwards", "In place of raising the cap, pin everyone to the cheapest model. Spend is decided by the model and not the cap, so apply it across the board", "Refuse to raise the cap. Never changing a cap once set is the principle of control, and allowing an exception makes that control collapse"],
  a:[0], e:"Managing spend: the default model and effort matter more than the cap." },
{ id:'ccdvp-4-08', d:4, o:0, q:"An alert for falling quality has fired. Which is the “first response”?",
  c:["Establish “is it real?” and “what changed?” Read dashboards, logs and recent deploys, and look for candidate causes in the latest production changes", "Roll the model version back by one first. A model change is the most common cause of falling quality, so reverting ahead of checking is faster", "Add “maintain quality” to the prompt and watch. Try the lightest remedies in order, and think about the next move only if that does not work", "Send users a survey to confirm they feel the drop. Alerts are often false, so back it up with people's voices before taking any action"],
  a:[0], e:"Show what broke, why, and a proposed fix." },
{ id:'ccdvp-4-09', d:4, o:1, q:"An incident-response agent judged that “this should be rolled back.” Which behavior is right?",
  c:["Run the rollback after the on-call engineer approves. Before approval it stays a proposal, and the fix goes out as a draft PR", "The agent runs the rollback at once. Waiting for approval only prolongs the outage, so reporting after the fact is enough", "The agent pushes the fix directly to main. Going through a PR delays recovery, so the path is shortened during an incident", "The agent sends the customers an apology email and then rolls back. Notice comes first, and sending does not wait for a person"],
  a:[0], e:"Replies to customers go as far as a draft, and a person sends them. A person is paged only for a P1." },
{ id:'ccdvp-4-10', d:4, o:1, q:"An agent is to write the postmortem. Which way of writing is called for?",
  c:["Rebuild the timeline with timestamps from evidence (messages, alerts). Separate root cause from contributing factors, describe system behavior, and give actions an owner and a date", "Write a three-line summary of the incident. Long documents go unread, so leave out the rebuilding of the timeline and put the cause and the actions into a single line for each", "Identify and record the responder's errors of judgment. Unless it is known who got what wrong there is no preventing a repeat, so individuals are named in the document itself", "“Take care” and “make it known” will do as actions. Attaching an owner and a date turns it into pursuing blame, so make them an aspiration for the whole team to work towards"],
  a:[0], e:"Blameless. For a customer-facing report, name the reader first, count the impact, and put internal detail in a separate appendix." },
{ id:'ccdvp-5-09', d:5, o:0, q:"CLAUDE.md was rewritten to be shorter. Which way of checking is right?",
  c:["Regression-test a settings change like code. Run the eval suite, and review before merge any change that lowers the pass rate", "Try it by hand a few times and merge if nothing is wrong. CLAUDE.md is instructions, so eyes are enough and no tests are needed", "Have the model read the diff of CLAUDE.md before and after the change, and ask it “will the behavior stay the same as before?”", "Use it in production for a week and then decide whether to keep it. An eval cannot reproduce what real-world use looks like"],
  a:[0], e:"An eval is 20 to 50 tasks gathered from real work, plus checks that decide whether the result is acceptable." },
{ id:'ccdvp-5-10', d:5, o:0, q:"In an agent eval, the agent rewrote the grading tests and passed. Which is the remedy?",
  c:["Keep the grading checks out of the checkout it runs in, and grade from a copy taken before the run. Limit the folders it may change too", "Write “do not rewrite the tests” in the system prompt. With the instruction it will not rewrite them, so the grading setup can stay as it is", "Make the test files read-only. Protecting them with OS permissions is enough, and the effort of keeping them out of the checkout is unneeded", "Review by hand the evals whose pass rate is unnaturally high. Rewrites are found by eye, so the automated grading does not need to change"],
  a:[0], e:"Check behavior, not wording. Do not use `--bare` for an eval that verifies settings." },
{ id:'ccdvp-5-11', d:5, o:0, q:"An eval verifying the effect of CLAUDE.md and hooks was being run with `claude -p --bare`. What is wrong with that?",
  c:["`--bare` does not load the CLAUDE.md, Skills and hooks under test, so it is not used for verifying settings", "`--bare` starts in the same setup every time, so it is ideal here: results are stable and only the diff shows", "`--bare` disables the tools, so it cannot be used to verify hooks but can still be used to verify CLAUDE.md", "`--bare` is the option that makes the output JSON, so grading gets easier. It has no effect on loading settings"],
  a:[0], e:"`--bare` is an option for automated runs that start in the same setup every time. It does not suit verifying settings." },
{ id:'ccdvp-5-12', d:5, o:2, q:"An eval found cases where the wrong tool is called and cases where an argument value has the wrong format. Which is the way to fix them?",
  c:["Fix only the part at fault: the description for a wrong tool, the schema and input examples for a wrong format. Merge duplicates into one tool with an argument, and compare by eval", "For both, add “call the right tool in the right format” to the system prompt. Adding an instruction is the quickest of the options, and the tool definitions need not be touched at all", "For both, change to a higher model. The accuracy of tool choice and of format is decided by the ability of the model, so this works more surely than fixing the definitions would", "For both, add ten few-shot examples. With plenty of examples the choice of tool and the format both settle down, and there is no need to fix the descriptions or the schema at all"],
  a:[0], e:"A description runs three to four sentences or more: what it does, when to use it and when not, what each argument means, and what it does not return." },
{ id:'ccdvp-6-07', d:6, o:0, q:"An agent stops its work partway. Which is the first move under “choosing between effort and model”?",
  c:["Raise effort by one level. Effort is “how hard it tries”: effort for too little or too much work, the model for lack of ability", "Change to a higher model. Stopping partway is a lack of ability, so touching effort changes nothing and the model is the first move", "Set effort to maximum. It stops when effort is low, so start at maximum; the added cost is smaller than the loss from stopping", "Raise the temperature. With more varied output it is less likely to stop partway, with fewer side effects than effort or model"],
  a:[0], e:"One level at a time from the default. After changing the model, start effort again from the default. Too high brings overthinking and work nobody asked for." },
{ id:'ccdvp-6-08', d:6, o:0, q:"The input tokens of a tool-heavy agent are swelling. Which gives the way to find the cause and the order in which to apply fixes?",
  c:["Print usage.input_tokens on every call to see which part is growing. Caching first, then programmatic tool calling", "Lower max_tokens. Shorter output cuts the next turn's input and the resent tool results, so it works unmeasured", "Halve the number of tools. Input tokens are proportional to the tool definitions, so no measuring is needed", "Programmatic tool calling first, and caching if that fails. Caching is the last resort; measure after that"],
  a:[0], e:"Everything is sent again on each request. With programmatic tool calling, only the output reaches Claude." },
{ id:'ccdvp-6-09', d:6, o:0, q:"To cache the tool definitions, cache_control was put on the last tool. Which caution is correct?",
  c:["Changing even one tool definition invalidates the whole cache. Below the minimum length, nothing is cached and no error is raised", "Even when a tool definition is changed, the cache remains valid for the part that comes before the tool that was changed", "Below the minimum length an error is returned, so if there is no error you can take it that the definitions are being cached", "cache_control goes on the first tool. When it is put on the last tool, only that last single tool ends up being cached"],
  a:[0], e:"Putting it on the last tool caches the whole set of tool definitions." },
{ id:'ccdvp-6-10', d:6, o:0, q:"Which correctly pairs work where “programmatic tool calling” pays off with work where it pays off less?",
  c:["Pays off: a set of lookups that do not depend on one another (results go to the script; only output reaches Claude). Less: work that reads each result to decide the next step", "Pays off: work that reads each result to decide the next step (Claude sees each result and can judge from it). Less: a set of lookups that do not depend on one another", "Pays off: work with only one tool (the script stays simple and is easy to write). Less: work with many tools (the script gets complex and is harder to get right)", "Pays off: work with long output (only the output arrives, so the amount is reduced). Less: work with short output (there is little room left to reduce anything)"],
  a:[0], e:"Claude writes a script that calls the tools, and the code execution tool runs it." },
{ id:'ccdvp-6-11', d:6, o:1, q:"One response contained three tool_use blocks. Which is the right way to return the results?",
  c:["Collect them all, run them at once, and return the results together in one user message. Returning them separately reduces later parallel calls", "Run them one at a time in order and return each in a separate user message. The order is kept, which is safe and makes errors easier to isolate", "Run and return only the first one, and have the model call the rest again on the next turn. One per turn is the way that works most reliably", "Join the three results into a single string and return it in a single tool_result. For the tool_use_id, the first of the three will do"],
  a:[0], e:"In streaming, the tool name arrives first, in content_block_start." },
{ id:'ccdvp-7-11', d:7, o:0, q:"A PreToolUse hook was meant to stop a dangerous command, but the command ran. What is the first thing to check?",
  c:["Check that the exit code is 2. 0 is success, 2 blocks, and anything else is a non-blocking error. 1 does not block", "Check that the hook is not set as PostToolUse. If it is PreToolUse, it stops the call whatever the exit code is", "Check that the same prohibition is written in CLAUDE.md. Both the hook and CLAUDE.md are needed for it to hold", "Check that the permission mode is not bypass. In any mode other than bypass, a hook is certain to take effect"],
  a:[0], e:"PreToolUse is the only means that can stop a call before it runs. It can also return permissionDecision (allow, deny, ask) as JSON." },
{ id:'ccdvp-7-12', d:7, o:0, q:"With `updatedInput` in a PreToolUse hook, you want the command to run with a secret in it masked. Which is the point to watch?",
  c:["`updatedInput` replaces the whole input, so return the unchanged fields as well", "`updatedInput` returns the diff only. Including unchanged fields duplicates them", "`updatedInput` works in PostToolUse only. PreToolUse can do nothing but deny", "Returning `updatedInput` makes permissionDecision ignored, so the call always runs"],
  a:[0], e:"PostToolUse comes after execution and cannot undo it, but exit code 2 can return a message and have it corrected." },
{ id:'ccdvp-7-13', d:7, o:0, q:"A design where a hook returns `ask` was brought into an unattended `claude -p` pipeline. What happens?",
  c:["Nobody is there to answer the ask, so it becomes a denial. A deny reason is shown to Claude, an ask reason to a person", "The ask is converted to allow automatically. Confirmation is skipped in unattended runs, and a hook's ask is ignored", "The pipeline stops, waiting on for a person's answer. There is no timeout, so it does not move until someone replies", "The ask becomes an error and Claude Code exits abnormally. The pipeline as a whole is then treated as having failed"],
  a:[0], e:"Unattended runs use `dontAsk`. `bypass` is for isolated environments only." },
{ id:'ccdvp-7-14', d:7, o:0, q:"`curl` was denied at the tool level, but the agent communicated with the outside through a shell script. Which explanation is right?",
  c:["A tool-level denial does not stop communication from the shell. The sandbox's OS-level domain allowlist is what stops it", "Add wget and python to the deny list too. Listing every command that can communicate prevents it, so no sandbox is needed", "Write “do not communicate externally” in CLAUDE.md. An instruction is obeyed, so neither deny entries nor a sandbox is needed", "Set the permission mode to plan. Plan mode can only read, so communication stops as well, which is simpler than a sandbox"],
  a:[0], e:"It can be configured not to start at all when the sandbox cannot be launched." },
{ id:'ccdvp-7-15', d:7, o:0, q:"Which account of the permission mode `auto` is correct?",
  c:["A classifier reviews intent but does not look at correctness. Combine it with a Stop hook that runs the tests", "A classifier reviews correctness as well, so the test hook is unneeded and it serves unattended runs as is", "It is the mode that skips every confirmation, so use it in isolated environments only, and never in CI", "It is the mode that allows reading only, so use it for drafting plans and switch modes in order to write"],
  a:[0], e:"`bypass` is for isolated environments only. `plan` is read-only." },
{ id:'ccdvp-7-16', d:7, o:2, q:"A team is operating a shared agent. Which form is called for on identity and credentials?",
  c:["Run it under a service account as the agent's own identity, with its actions kept in the audit log under that account. Credentials are attached at the network boundary", "Run it under the personal account of whoever started it. The audit log shows whose operation it was, and there is no overhead of managing additional service accounts", "Run it under a shared admin account. It never stops for lack of permission, and it is enough for the audit log to record the actions as having been done by “the agent”", "Pass the credentials into the sandbox as environment variables. Environment variables leave nothing in the code, and the agent can read them itself whenever it needs to"],
  a:[0], e:"Three gates on a connector: enabled for the organization, included in the role, connected by the member. Read wide and write narrow." },
{ id:'ccdvp-8-10', d:8, o:0, q:"A bug fix is being left to an agent. Which way of proceeding is recommended?",
  c:["Write and commit a failing test first, and have it pass without rewriting the test. Stop edits to test files with a hook", "Have it write the fix, and then have it write a test that fits the fix. When the test passes it is done; no hook is needed", "Have it write only the fix with no test, and check the behavior by hand. Tests can be added later; no hook is needed", "Have it write the fix and the test together, done when both exist. Stopping edits to tests makes the fix impossible"],
  a:[0], e:"The self-verification loop: gather verification into one command, and show a goal that can be confirmed by a number." },
{ id:'ccdvp-8-11', d:8, o:0, q:"Which is the criterion for the upper limit on the number of agents run in parallel?",
  c:["The number one person can review properly. Isolate parallel sessions in worktrees, and do work that shares files in one, in turn", "The number of CPU cores. Beyond that execution slows down, so go parallel up to the core count and review in one batch afterwards", "The number set by the API rate limit. Maximize within the range where no 429 appears, and leave review to AI to unload people", "There is no upper limit. Leave review to AI and the number can grow, and isolating in worktrees means no conflicts arise either"],
  a:[0], e:"Tell `/compact` what to keep, set the completion condition with `/goal`, and check external state at intervals with `/loop`." },
{ id:'ccdvp-8-12', d:8, o:1, q:"AI code review is being introduced. Which is the right stance on approval?",
  c:["AI findings neither approve nor block. Approval is given by people under branch protection, and there is no path for the agent that wrote the code to approve it", "A PR that the AI judges to have “no problems” is merged automatically. Human review is needed only when the AI raises a question, which lightens the load on people", "If an agent other than the one that wrote the code approves, human approval is unneeded. An independent context looks harder at the change than a person would", "Approval can be skipped for a PR with no AI findings. If people look only when there are findings, review time is concentrated on the PRs that actually have them"],
  a:[0], e:"The review policy goes in REVIEW.md. When the same finding appears twice, reflect it in CLAUDE.md. Managed Code Review only posts findings." },
{ id:'ccdvp-8-13', d:8, o:2, q:"You want an unattended agent that inspects a repository at intervals and opens Issues. Which of the “options for automated runs” fits?",
  c:["A scheduled run in the cloud (a set of prompt, repository, connectors and trigger), or headless from CI (`claude -p` with JSON output)", "Embed it in your own product with the Agent SDK. The SDK is required for periodic runs; scheduled runs and headless cannot open Issues", "Leave an interactive session running and keep it going with `/loop`. While the session lives it is a periodic run and works unattended", "Start the GitHub Action claude-code-action on every PR. It can be started by cron even with no PR at all, and can open Issues as well"],
  a:[0], e:"`--bare` starts in the same setup every time. The Agent SDK is for embedding in your own product." },
{ id:'ccdvp-8-14', d:8, o:3, q:"Which account of the controls on publishing Skills to the organization's library is correct?",
  c:["Three levels: no publishing, review required, and free. Loosening is free, but check the effect on existing use when tightening", "Make publishing free, and delete Skills that cause problems later. Prior review hinders adoption, and tightening needs no check", "Make all publishing review-required and unchangeable. Levels blur the control, and no call to loosen or tighten is ever needed", "Forbid publishing, with Skills used only in each person's repository. Share by managed settings alone and build no library"],
  a:[0], e:"Managed settings enforce fixed permission rules, disabling bypass, limits on MCP and hooks, marketplace restrictions and a minimum version." },
];
